/*
 * more-songs.js
 * Extra songs for Free Play only. Daily never uses them, so adding songs here
 * doesn't change any daily lineup. Loaded only when Free Play opens.
 * Like songs.js, only iTunes IDs are stored, not titles.
 *
 * Where the songs come from (all clean versions iTunes sells in the US):
 *   - Billboard number ones on the Country, R&B/Hip-Hop, Mainstream Rock,
 *     Alternative and Hot Latin charts
 *   - K-pop number ones on Korea's Circle (Gaon) Digital Chart
 *   - Openings and endings of the 400 most popular shows on AniList,
 *     with song titles from AnimeThemes
 *   - Apple's current top 100 in 18 genres
 *   - Billboard Year-End Hot 100 ranks 41-100 (1970-2025) and the 1960s
 * Songs with titles only in Japanese or Korean script are left out: the
 * guess box can't compare them.
 *
 * tier: these are deeper cuts than Daily's songs, so most are Hard or Expert.
 * genres: same as songs.js
 * anime: the AniList ID of the show an anime song is from (no names, so the
 *   source doesn't spoil it). Naming that show in the guess box counts.
 */

